'use strict';
// Local presentation data only. No fetch, production queue, storage or filesystem actions.
const prompts=['晨光里的橘猫，蓝色陶瓷花瓶，写实摄影','窗边的白色花朵，柔和侧光，室内静物','木质书桌与书本，午后阳光穿过窗帘','雨后的街角，路灯和湿润的石板'];
const mockTasks=Array.from({length:12},(_,i)=>({id:i+1,prompt:prompts[Math.floor(i/3)],batch:Math.floor(i/3),model:i===1||i===2?'Qwen 2.1':'FLUX.2',status:i<2?'已完成':i===2?'生成中':'等待中',cls:i<2?'done':i===2?'running':'waiting',time:i===0?'31.8s':i===1?'67.3s':'—'}));
const uiIcon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',pointer:'<path d="m5 3 14 10-7 1-3 7z"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',play:'<path d="m8 4 11 8-11 8z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5h4"/>',plus:'<path d="M12 4v16M4 12h16"/>'})[n]}</svg>`;
function menuHeader(name){return `<header class="menu"><div class="brand">${uiIcon('layers')}<h1>本地绘图工作台</h1><small> / ${name}</small></div><div class="right"><span>4 个模型</span><span>RTX 5070 Ti · 16GB</span><span>工作区：批量管理</span></div></header><div class="optionbar"><div class="row"><button data-demo="恢复执行">${uiIcon('play')} 恢复</button><button data-demo="暂停派发">暂停</button><span class="separator"></span><button data-demo="打乱所有等待任务">打乱等待</button><button data-demo="停止当前任务">停止当前</button><button class="optional" data-demo="清空队列（保留图片）">清空队列</button></div><div class="row"><span class="sub optional">串行执行 · 示意</span><button class="primary" data-demo="加入生成任务">${uiIcon('plus')} 新批次</button></div></div>`;}
function footer(){return `<footer class="statusbar"><div class="row"><span>12 个任务 · 2 完成 · 1 生成 · 9 等待</span><span>所有状态均为原型演示</span></div><div class="row"><span>ComfyUI / 本地</span><button data-demo="打开系统日志">日志</button><button data-demo="打开本地输出目录">本地目录</button></div></footer>`;}
function batchNav(){return `<aside class="panel"><div class="panel-head"><h2>批次 / 历史</h2><span class="sub">＋</span></div><div class="batch-list"><button class="batch-item selected" data-batch="all">当前批次<small>静物与街景</small><div class="counts">4 提示词 / 12 任务</div></button>${['晨光与蓝色陶瓷','窗边的白色花朵','午后的书桌','雨后的街角'].map((p,i)=>`<button class="batch-item" data-batch="${i}">${p}<small>提示词组 ${String(i+1).padStart(2,'0')} · 3 张</small></button>`).join('')}</div><div class="nav-foot">提示词历史<small style="display:block">可折叠与载入批次</small><hr style="border:0;border-top:1px solid #494950;margin:10px 0">已生成作品<br>收藏与点踩过滤<br>导出 / 本地目录</div></aside>`;}
function tools(){return `<aside class="tools" aria-label="工作区工具">${['pointer','layers','grid','history','settings'].map((n,i)=>`<button title="${['选择任务','任务列表','缩略图','提示词历史','工作区设置'][i]}" aria-label="${['选择任务','任务列表','缩略图','提示词历史','工作区设置'][i]}" data-demo="${['选择任务','任务列表','缩略图','提示词历史','工作区设置'][i]}">${uiIcon(n)}</button>`).join('')}</aside>`;}
function selectionBar(){return `<div class="selection-bar"><span data-selection-label>已选择 2 个等待任务</span><div class="row"><button data-demo="选中任务置顶">置顶</button><button data-demo="跳过选中任务">跳过</button><button data-demo="删除选中任务">删除</button></div></div>`;}
function filterbar(){return `<div class="table-toolbar"><input type="search" data-search placeholder="搜索提示词 / 模型" aria-label="搜索提示词或模型"><select data-filter aria-label="筛选任务状态"><option value="all">所有状态</option><option value="等待中">等待中</option><option value="生成中">生成中</option><option value="已完成">已完成</option></select><span class="sub" data-visible-count>12 个任务</span></div>`;}
function taskRows(tasks=mockTasks){return `<div class="table-scroll"><table class="task-table"><thead><tr><th class="check-col"><input type="checkbox" data-check-all aria-label="选中全部可见任务"></th><th class="id-col">#</th><th>提示词</th><th class="state-col">状态</th><th class="model-col">模型</th><th class="time-col">耗时</th></tr></thead><tbody>${tasks.map(t=>`<tr data-task="${t.id}" data-state="${t.status}" data-group="${t.batch}" class="${t.id===4||t.id===5?'selected':''}" tabindex="0" role="row" aria-label="任务 ${t.id} ${t.prompt}"><td><input type="checkbox" data-check="${t.id}" aria-label="选择任务 ${t.id}" ${t.id===4||t.id===5?'checked':''}></td><td class="id-col">${String(t.id).padStart(2,'0')}</td><td title="${t.prompt}">${t.prompt} <small>· ${((t.id-1)%3)+1}/3</small></td><td><span class="state ${t.cls}">${t.status}</span></td><td>${t.model}</td><td class="time-col">${t.time}</td></tr>`).join('')}</tbody></table></div>`;}
function fold(title,content,open=true){return `<details class="fold" ${open?'open':''}><summary><span>${title}</span><small>···</small></summary><div class="content">${content}</div></details>`;}
function inputField(label,value,type='number'){const id='p-'+label.replace(/\s/g,'');return `<div class="form-row"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${value}" ${type==='number'?'step="1"':''}></div>`;}
function modelProperties(){return fold('模型与推荐',`<div class="form-row"><label for="model-select">生图模型</label><select id="model-select" data-model><option>FLUX.2 klein 4B</option><option>Z-Image-Turbo</option><option>Qwen-Image 2.1</option><option>SDXL Turbo</option></select></div><p class="hint" data-model-hint>FP8 · 推荐 1024 方图 / 4 步 / CFG 1</p><p class="hint">切换可更新等待任务；当前生成保持原模型。</p>`)+fold('生成参数',`<div class="form-row"><label for="size-select">尺寸 / 比例</label><select id="size-select"><option>1024 × 1024 · 1:1</option><option>1280 × 720 · 16:9</option><option>1024 × 768 · 4:3</option><option>768 × 1024 · 3:4</option></select></div>${inputField('步数','4')}${inputField('CFG','1')}${inputField('每条数量','3')}${inputField('随机种子','-1')}<div class="row spread" style="margin-top:10px"><small>每张独立随机</small><button data-demo="恢复当前模型推荐参数">恢复推荐</button></div>`)+fold('提示词前后缀',`${inputField('前缀','','text')}${inputField('后缀','','text')}`,false)+fold('提示词历史','<p class="hint">晨光与蓝色陶瓷 · 3 条<br>雨后的街角 · 12 条<br>点击载入批次的位置</p><button data-demo="清空提示词历史">清空历史</button>',false);}
function inspector(label='选中 2 个等待任务'){return `<aside class="panel"><div class="tabs" role="tablist" aria-label="任务属性面板"><button role="tab" data-tab="properties" aria-selected="true">属性</button><button role="tab" data-tab="preview" aria-selected="false">预览</button></div><div class="props-label" data-inspect-label>${label}</div><div class="panel-body flush tab-content" data-content="properties">${modelProperties()}${fold('选中任务',`<dl class="properties"><dt>提示词</dt><dd class="text" data-inspect-prompt>窗边的白色花朵，柔和侧光，室内静物</dd><dt>状态</dt><dd data-inspect-state>等待中</dd><dt>模型</dt><dd data-inspect-model>FLUX.2 klein 4B</dd></dl>`,false)}</div><div class="panel-body tab-content" data-content="preview" hidden><div class="preview-small"><img src="../assets/flux2.png" alt="FLUX.2 实际测试图"></div><dl class="properties"><dt>模型</dt><dd>FLUX.2 klein 4B</dd><dt>尺寸</dt><dd>1024 × 1024 · 1:1</dd><dt>种子</dt><dd>0</dd><dt>步数</dt><dd>4</dd></dl><button data-demo="下载当前图片">下载原图</button></div><div class="panel-footer"><button data-demo="将模型配方应用到等待任务">应用到等待任务</button></div></aside>`;}
function miniPreview(){return `<div class="mini-preview"><img src="../assets/flux2.png" alt="本机 FLUX.2 1024 方图测试输出"><div><p>已生成作品 / 晨光里的橘猫</p><small>FLUX.2 klein 4B · 1024 × 1024 · 1:1</small><small>种子 0 · 4 步 · CFG 1</small><div class="row" style="margin-top:8px"><button data-demo="收藏当前图片">收藏</button><button data-demo="复用原图提示词">复用提示词</button><button data-demo="导出图片">导出</button></div></div></div>`;}
function batchInput(){return `<section class="batch-input"><div class="batch-input-head"><h2>批量输入</h2><span class="sub">每行一条提示词 / 历史　⌄</span></div><textarea aria-label="批量提示词">晨光里的橘猫，蓝色陶瓷花瓶，写实摄影&#10;窗边的白色花朵，柔和侧光，室内静物&#10;木质书桌与书本，午后阳光穿过窗帘</textarea><div class="recipe-inline"><div class="row"><span class="sub">每条</span><select aria-label="每条抽奖数量"><option>3 张</option><option>1 张</option><option>6 张</option></select><small>3 条 × 3 张 = 9 个任务</small></div><button class="primary" data-demo="提交新的生成批次">加入队列</button></div></section>`;}
let feedbackTimer;
function inform(msg){const el=document.getElementById('feedback');el.textContent='原型演示：'+msg+'（不操作真实任务）';el.hidden=false;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>el.hidden=true,3000);}
function refreshSelection(){const root=document.getElementById('stage');const checks=[...root.querySelectorAll('[data-check]')];checks.forEach(c=>c.closest('tr').classList.toggle('selected',c.checked));const selected=checks.filter(c=>c.checked).length;root.querySelectorAll('[data-selection-label]').forEach(el=>el.textContent=`已选择 ${selected} 个任务`);}
function inspect(id){const t=mockTasks.find(t=>t.id===Number(id));if(!t)return;document.querySelectorAll('[data-inspect-label]').forEach(el=>el.textContent=`任务 ${String(t.id).padStart(2,'0')} · ${t.status}`);document.querySelectorAll('[data-inspect-prompt]').forEach(el=>el.textContent=t.prompt);document.querySelectorAll('[data-inspect-state]').forEach(el=>el.textContent=t.status);document.querySelectorAll('[data-inspect-model]').forEach(el=>el.textContent=t.model==='FLUX.2'?'FLUX.2 klein 4B':t.model);document.querySelectorAll('.tile,.wait-row').forEach(el=>el.classList.toggle('selected',el.dataset.inspect===String(id)));}
function filterTasks(){const root=document.getElementById('stage');const search=root.querySelector('[data-search]')?.value.toLowerCase()||'';const state=root.querySelector('[data-filter]')?.value||'all';const group=root.querySelector('.batch-item.selected')?.dataset.batch||'all';let count=0;root.querySelectorAll('[data-task]').forEach(el=>{el.hidden=!(el.textContent.toLowerCase().includes(search)&&(state==='all'||el.dataset.state===state)&&(group==='all'||el.dataset.group===group));if(!el.hidden)count++;});root.querySelectorAll('[data-visible-count]').forEach(el=>el.textContent=`${count} 个任务`);root.querySelectorAll('[data-prompt-group]').forEach(el=>el.hidden=group!=='all'&&el.dataset.promptGroup!==group);}
document.addEventListener('input',e=>{if(e.target.matches('[data-search]'))filterTasks();});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){refreshSelection();inspect(e.target.dataset.check);}if(e.target.matches('[data-check-all]')){document.querySelectorAll('[data-task]:not([hidden]) [data-check]').forEach(c=>c.checked=e.target.checked);refreshSelection();}if(e.target.matches('[data-filter]'))filterTasks();if(e.target.matches('[data-model]')){const i=e.target.selectedIndex;document.querySelector('[data-model-hint]').textContent=['FP8 · 推荐 1024 方图 / 4 步 / CFG 1','蒸馏 · 推荐 1024 方图 / 9 步 / CFG 1','INT8 · 推荐 768 方图 / 25 步 / CFG 1','快速草稿 · 推荐 512 方图 / 4 步 / CFG 1'][i];}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.demo){inform(b.dataset.demo);return;}if(b?.dataset.tab){document.querySelectorAll('[data-tab]').forEach(el=>el.setAttribute('aria-selected',String(el===b)));document.querySelectorAll('[data-content]').forEach(el=>el.hidden=el.dataset.content!==b.dataset.tab);return;}if(b?.dataset.batch){document.querySelectorAll('[data-batch]').forEach(el=>el.classList.toggle('selected',el===b));filterTasks();return;}const inspectEl=e.target.closest('[data-inspect]');if(inspectEl)inspect(inspectEl.dataset.inspect);const tr=e.target.closest('tr[data-task]');if(tr&&!e.target.matches('input')){const check=tr.querySelector('[data-check]');check.checked=!check.checked;refreshSelection();inspect(tr.dataset.task);}});
document.addEventListener('keydown',e=>{const target=e.target.closest('tr[data-task],[data-inspect]');if(target&&(e.key==='Enter'||e.key===' ')&&!e.target.matches('input,button')){e.preventDefault();if(target.matches('tr'))target.click();else inspect(target.dataset.inspect);}});
